  describe('retries', () => {
    const noDelay = { sleep: async () => {}, random: () => 0 };

    const httpError = (status: number) =>
      Object.assign(new Error(`HTTP ${status}`), { status });

    // Each create() call consumes the next step: 'ok' returns a completion,
    // anything else is thrown. Steps beyond the list repeat the last one.
    function scripted(steps: Array<'ok' | Error>) {
      const calls: string[] = [];
      let i = 0;
      const factory = (ep: LLMEndpoint) =>
        ({
          chat: {
            completions: {
              create: async () => {
                calls.push(ep.baseURL);
                const step = steps[Math.min(i, steps.length - 1)];
                i += 1;
                if (step === 'ok' || step === undefined) {
                  return {
                    choices: [{ message: { content: 'translated' } }],
                  };
                }
                throw step;
              },
            },
          },
        }) as unknown as Pick<OpenAI, 'chat'>;
      return { calls, factory };
    }

    it('retries on a 5xx then succeeds', async () => {
      const { calls, factory } = scripted([httpError(503), 'ok']);
      const t = new OpenAICompatTranslator(
        endpoint('https://p'),
        undefined,
        factory,
        noDelay,
      );
      const out = await t.translate(segment, [], 'vi');
      expect(out).toBe('translated');
      expect(calls).toEqual(['https://p', 'https://p']);
    });

    it('fails immediately on a non-retryable 4xx', async () => {
      const { calls, factory } = scripted([httpError(400), 'ok']);
      const t = new OpenAICompatTranslator(
        endpoint('https://p'),
        undefined,
        factory,
        noDelay,
      );
      await expect(t.translate(segment, [], 'vi')).rejects.toBeInstanceOf(
        TranslationError,
      );
      expect(calls).toEqual(['https://p']);
    });

    it('stops after 3 attempts and surfaces the failure', async () => {
      const delays: number[] = [];
      const { calls, factory } = scripted([
        httpError(500),
        httpError(500),
        httpError(500),
        'ok',
      ]);
      const t = new OpenAICompatTranslator(
        endpoint('https://p'),
        undefined,
        factory,
        { sleep: async (ms) => { delays.push(ms); }, random: () => 0 },
      );
      await expect(t.translate(segment, [], 'vi')).rejects.toBeInstanceOf(
        TranslationError,
      );
      expect(calls).toEqual(['https://p', 'https://p', 'https://p']);
      expect(delays).toEqual([500, 1000]);
    });

    it('retries on 429 and network errors', async () => {
      const connErr = Object.assign(new Error('socket hang up'), {
        code: 'ECONNRESET',
      });
      const { calls, factory } = scripted([httpError(429), connErr, 'ok']);
      const t = new OpenAICompatTranslator(
        endpoint('https://p'),
        undefined,
        factory,
        noDelay,
      );
      const out = await t.translate(segment, [], 'vi');
      expect(out).toBe('translated');
      expect(calls).toEqual(['https://p', 'https://p', 'https://p']);
    });

    it('does not retry a malformed (empty) response', async () => {
      let n = 0;
      const factory = (ep: LLMEndpoint) =>
        ({
          chat: {
            completions: {
              create: async () => {
                n += 1;
                return {
                  choices:
                    n === 1
                      ? [{ message: { content: '  ' } }]
                      : [{ message: { content: 'translated' } }],
                };
              },
            },
          },
        }) as unknown as Pick<OpenAI, 'chat'>;
      const t = new OpenAICompatTranslator(
        endpoint('https://p'),
        undefined,
        factory,
        noDelay,
      );
      await expect(t.translate(segment, [], 'vi')).rejects.toBeInstanceOf(
        TranslationError,
      );
      expect(n).toBe(1);
