                  }
                  return inner.chat.completions.create({} as never);
                },
              },
            },
          } as Pick<OpenAI, 'chat'>;
        },
        noDelay,
      );
      const out = await t.translate(segment, [], 'vi');
      expect(out).toBe('fallback ok');
      expect(calls).toEqual(['https://p', 'https://p', 'https://p']);
    });
  });
});

